#include "explorer_icons.h"
#include "../kernel/window.h"

// Alpha-blended ARGB drawing
void draw_bitmap_argb(window_t *win, int x, int y, int w, int h, const uint32_t *data) {
    if (!win || !win->surface) return;
    
    for (int j = 0; j < h; j++) {
        for (int i = 0; i < w; i++) {
            uint32_t pixel = data[j * w + i];
            uint8_t a = (pixel >> 24) & 0xFF;
            
            if (a == 0) continue; // Fully transparent
            
            int px = x + i;
            int py = y + j;
            
            if (px < 0 || px >= win->surface_w || py < 0 || py >= win->surface_h)
                continue;
            
            if (a == 255) {
                // Fully opaque
                win->surface[py * win->surface_w + px] = pixel;
            } else {
                // Blend
                uint32_t bg = win->surface[py * win->surface_w + px];
                uint8_t br = (bg >> 16) & 0xFF;
                uint8_t bg_g = (bg >> 8) & 0xFF;
                uint8_t bb = bg & 0xFF;
                
                uint8_t fr = (pixel >> 16) & 0xFF;
                uint8_t fg = (pixel >> 8) & 0xFF;
                uint8_t fb = pixel & 0xFF;
                
                uint8_t r = (fr * a + br * (255 - a)) / 255;
                uint8_t g = (fg * a + bg_g * (255 - a)) / 255;
                uint8_t b = (fb * a + bb * (255 - a)) / 255;
                
                win->surface[py * win->surface_w + px] = 0xFF000000 | (r << 16) | (g << 8) | b;
            }
        }
    }
}

